messages.content:
Berikut manifest game **Vertebrata vs Invertebrata Run** dengan tema Cartoon dan kesulitan Normal. Asumsi penting: item hewan air seperti lumba-lumba, ubur-ubur, dan cumi-cumi dipakai sebagai jebakan miskonsepsi "semua hewan air adalah ikan".

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "vertebrata-invertebrata-run", title: "Vertebrata vs Invertebrata Run", seed: "vert-invert-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Biologi",
    concept: "Klasifikasi hewan vertebrata dan invertebrata berdasarkan ada tidaknya tulang belakang",
    objectives: [
      "Mengelompokkan hewan berdasarkan ada tidaknya tulang belakang",
      "Meluruskan miskonsepsi bahwa semua hewan air adalah ikan"
    ],
    misconceptions: ["Semua hewan yang hidup di air adalah ikan"],
    mode: "category",
    categories: [
      { id: "vertebrata",   label: "Vertebrata",   color: "#2F80ED" },
      { id: "invertebrata", label: "Invertebrata", color: "#3FA34D" }
    ],
    items: [
      { id: "ikan-mas",       label: "Ikan mas",        category: "vertebrata",   explain: "Ikan bertulang belakang sejati, termasuk vertebrata." },
      { id: "katak",          label: "Katak",           category: "vertebrata",   explain: "Amfibi yang memiliki tulang belakang." },
      { id: "burung-merpati", label: "Burung merpati",  category: "vertebrata",   explain: "Aves bertulang belakang, termasuk vertebrata." },
      { id: "ular-kobra",     label: "Ular kobra",      category: "vertebrata",   explain: "Reptil bertulang belakang meski tidak berkaki." },
      { id: "lumba-lumba",    label: "Lumba-lumba",     category: "vertebrata",   explain: "Mamalia air bertulang belakang; bukan ikan." },
      { id: "kucing",         label: "Kucing",          category: "vertebrata",   explain: "Mamalia darat yang memiliki tulang belakang." },
      { id: "cacing-tanah",   label: "Cacing tanah",    category: "invertebrata", explain: "Annelida tanpa tulang belakang." },
      { id: "ubur-ubur",      label: "Ubur-ubur",       category: "invertebrata", explain: "Hewan air tanpa tulang belakang; bukan ikan." },
      { id: "cumi-cumi",      label: "Cumi-cumi",       category: "invertebrata", explain: "Moluska air tanpa tulang belakang; bukan ikan." },
      { id: "belalang",       label: "Belalang",        category: "invertebrata", explain: "Arthropoda tanpa tulang belakang." },
      { id: "siput",          label: "Siput",           category: "invertebrata", explain: "Moluska berbadan lunak tanpa tulang belakang." },
      { id: "bintang-laut",   label: "Bintang laut",    category: "invertebrata", explain: "Echinodermata tanpa tulang belakang." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",  w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak", w: 90, h: 40, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
